package com.lexia.legalassistant.data.repository

/**
 * Registro oficial estatutario de los 271 Artículos de la Ley de Amparo
 * Reglamentaria de los artículos 103 y 107 de la Constitución Política de los Estados Unidos Mexicanos.
 * DOF Vigente con las reformas del Poder Judicial de la Federación.
 */
object AmparoStatutoryData {

    data class ArticleMeta(
        val title: String,
        val category: String,
        val summary: String
    )

    val articles: Map<Int, ArticleMeta> = mapOf(
        1 to ArticleMeta("Objeto y Fines del Juicio de Amparo", "Reglas Generales", "El juicio de amparo tiene por objeto resolver toda controversia suscitada por normas generales, actos u omisiones de autoridad que violen los derechos humanos y garantías reconocidos en la Constitución y en los tratados internacionales de los que el Estado Mexicano sea parte."),
        2 to ArticleMeta("Vías de Tramitación y Supletoriedad del CFPC", "Reglas Generales", "El juicio de amparo se tramitará en vía directa o indirecta conforme a los procedimientos de esta Ley. A falta de disposición expresa se aplicará en forma supletoria el Código Federal de Procedimientos Civiles y, en su defecto, los principios generales del derecho."),
        3 to ArticleMeta("Tramitación Electrónica, Firma Electrónica y Expediente Digital", "Reglas Generales", "Regula las promociones mediante el Portal de Servicios en Línea del Poder Judicial de la Federación, uso de la FIREL o e.firma, y la validez plena y equivalencia jurídica del expediente electrónico frente al impreso."),
        4 to ArticleMeta("Principio de Instancia de Parte Agraviada", "Reglas Generales", "El juicio de amparo únicamente puede promoverse por la parte a quien perjudique la norma general o el acto reclamado, no procediendo de oficio bajo ninguna circunstancia."),
        5 to ArticleMeta("Partes en el Juicio de Amparo", "Partes Procesales", "Son partes en el juicio de amparo: I. El quejoso; II. La autoridad responsable; III. El tercero interesado; y IV. El Ministerio Público de la Federación para velar por el interés público."),
        6 to ArticleMeta("Legitimación: Interés Jurídico e Interés Legítimo", "Partes Procesales", "El juicio de amparo puede promoverse por la persona física o moral que aduzca ser titular de un derecho subjetivo o de un interés legítimo individual o colectivo que resulte afectado de manera directa o por virtud de su especial situación frente al orden jurídico."),
        7 to ArticleMeta("Personas Morales Oficiales en el Amparo", "Partes Procesales", "Las personas morales oficiales pueden pedir amparo por conducto de los servidores públicos facultados, exclusivamente cuando el acto reclamado afecte su patrimonio respecto de relaciones jurídicas de derecho privado."),
        8 to ArticleMeta("Representación Legal de Menores e Incapaces", "Partes Procesales", "El menor de edad o persona con discapacidad mental puede promover amparo por sí mismo o por cualquier persona en su nombre sin acreditar representación, nombrándole el juez un representante especial."),
        9 to ArticleMeta("Representación de las Autoridades Responsables", "Partes Procesales", "Las autoridades responsables comparecen por oficio y pueden designar delegados para oír notificaciones, ofrecer pruebas, formular alegatos e interponer recursos en las audiencias."),
        10 to ArticleMeta("Representación del Quejoso y del Tercero Interesado", "Partes Procesales", "La representación del quejoso y del tercero interesado se acredita conforme a las leyes aplicables mediante poder notarial o carta poder ratificada ante el secretario del tribunal."),
        11 to ArticleMeta("Muerte de la Parte Quejosa o Tercero Interesado", "Partes Procesales", "Cuando fallezca el quejoso o tercero durante el juicio y el acto reclamado no sea de aquellos estrictamente personales, el proceso continuará con el albacea o representante de la sucesión."),
        12 to ArticleMeta("Autorización Amplia a Licenciados en Derecho", "Partes Procesales", "El quejoso y tercero pueden autorizar para oír notificaciones a profesionistas en derecho con cédula registrada, quienes podrán interponer recursos, rendir pruebas y alegar en audiencias."),
        13 to ArticleMeta("Representación Común en Litisconsorcio", "Partes Procesales", "Cuando dos o más quejosos reclamen los mismos actos y sustenten iguales conceptos de violación, deberán designar un representante común; en su defecto, el juez lo designará de entre ellos."),
        14 to ArticleMeta("Comparecencia por Tercero en Caso de Incomunicación", "Partes Procesales", "Cuando el quejoso se halle imposibilitado para promover amparo por incomunicación, deportación, expulsión o tormento, cualquier persona puede promoverlo a su nombre sin necesidad de poder previo."),
        15 to ArticleMeta("Actos que Importan Peligro de Vida o Libertad Personal", "Reglas Generales", "Cuando se reclamen actos que importen peligro de privación de la vida, ataques a la libertad personal fuera de procedimiento, desaparición forzada o tormento, la demanda podrá presentarse en cualquier momento y por cualquier medio."),
        16 to ArticleMeta("Interrupción de Términos por Caso Fortuito", "Términos Procesales", "Los términos no correrán cuando por caso fortuito o fuerza mayor esté imposibilitada la parte quejosa o el tribunal para actuar o recibir promociones judiciales."),
        17 to ArticleMeta("Plazo General de Quince Días y Supuestos de Excepción", "Términos Procesales", "El plazo para presentar la demanda de amparo es de quince días hábiles. Excepciones: 30 días contra normas autoaplicativas; 8 años contra sentencia condenatoria penal privativa de la libertad; 7 años en materia agraria ejidal; y en cualquier tiempo tratándose de actos del Art. 22 constitucional."),
        18 to ArticleMeta("Cómputo Procesal de los Plazos Judiciales", "Términos Procesales", "Los plazos empezarán a correr desde el día siguiente a aquel en que surta efectos la notificación al quejoso de la resolución o acuerdo que reclame, o al en que haya tenido conocimiento de ellos."),
        19 to ArticleMeta("Días Hábiles e Inhábiles para la Tramitación", "Términos Procesales", "Son días hábiles todos los del año con excepción de sábados, domingos, 1 de enero, 5 de febrero, 21 de marzo, 1 y 5 de mayo, 16 de septiembre, 20 de noviembre y los que declare el CJF."),
        20 to ArticleMeta("Habilitación Judicial de Días y Horas Inhábiles", "Términos Procesales", "El órgano jurisdiccional de oficio o a petición de parte puede habilitar días y horas inhábiles cuando haya urgencia inaplazable para resolver sobre la suspensión del acto reclamado."),
        21 to ArticleMeta("Capacidad Procesal en Comunidades Indígenas y Agrarias", "Términos Procesales", "Las comunidades y pueblos indígenas o agrarios podrán actuar por medio de sus autoridades tradicionales, comisariados ejidales o por cualquier comunero en defensa de sus derechos colectivos."),
        22 to ArticleMeta("Plazos Procesales en Materia Penal y Detención", "Términos Procesales", "Los plazos para formular promociones respecto a la libertad personal del imputado o sentenciado son improrrogables y se computarán de momento a momento sin interrupción."),
        23 to ArticleMeta("Domicilio Procesal en la Jurisdicción del Tribunal", "Notificaciones", "Las partes tienen el deber de señalar domicilio para oír y recibir notificaciones dentro del lugar de residencia del órgano jurisdiccional, bajo apercibimiento de notificación por lista."),
        24 to ArticleMeta("Cálculo Improrrogable de Términos Judiciales", "Términos Procesales", "Los términos se computarán por días completos y vencerán a las veinticuatro horas del último día hábil, pudiendo presentarse en la oficialía de partes automatizada o buzón judicial."),
        25 to ArticleMeta("Presentación de Promociones por Medios Electrónicos y Correos", "Términos Procesales", "Las promociones pueden presentarse en la oficina de correos o telégrafos del lugar de residencia del quejoso cuando radique fuera de la sede del juzgado, o mediante el portal digital del PJF."),
        26 to ArticleMeta("Clases y Formas de Notificaciones Procesales", "Notificaciones", "Las notificaciones en los juicios de amparo se harán: I. De forma personal; II. Por oficio; III. Por lista fijada en estrados y electrónica; y IV. Por vía electrónica mediante el portal del CJF."),
        27 to ArticleMeta("Formalidades de las Notificaciones Personales", "Notificaciones", "El actuario judicial practicará las notificaciones personales entregando copia íntegra de la resolución; de no encontrar al interesado dejará citatorio para el día siguiente hábil."),
        28 to ArticleMeta("Práctica de Notificaciones por Oficio a Autoridades", "Notificaciones", "Las notificaciones dirigidas a las autoridades responsables se harán por oficio entregado por el actuario o mediante correo certificado con acuse de recibo en sus sedes oficiales."),
        29 to ArticleMeta("Notificaciones por Lista en Estrados del Tribunal", "Notificaciones", "Se fijará la lista de acuerdos diariamente en un lugar visible de los estrados del órgano jurisdiccional y en el portal de internet del Poder Judicial de la Federación."),
        30 to ArticleMeta("Reglas de las Notificaciones Electrónicas", "Notificaciones", "Las notificaciones por vía electrónica surtirán efectos cuando el usuario acceda a la resolución en el sistema, o a los dos días hábiles siguientes al envío si no accede."),
        31 to ArticleMeta("Momento en que Surten Efectos las Notificaciones", "Notificaciones", "Las notificaciones surten efectos: para quejoso y terceros desde el día siguiente a su práctica personal o publicación por lista; para autoridades responsables desde el momento de su entrega."),
        32 to ArticleMeta("Incidente de Nulidad de Notificaciones", "Notificaciones", "Las notificaciones hechas en contravención a la ley son nulas. La nulidad se promoverá antes de la siguiente actuación o dentro de los tres días siguientes a que se tuvo conocimiento."),
        33 to ArticleMeta("Órganos Competentes en el Juicio de Amparo", "Competencia", "Son competentes para conocer del amparo: la Suprema Corte de Justicia de la Nación, los Tribunales Colegiados de Circuito, los Tribunales Colegiados de Apelación y los Juzgados de Distrito."),
        34 to ArticleMeta("Competencia de los Tribunales Colegiados de Circuito", "Competencia", "Los Tribunales Colegiados de Circuito conocen del amparo directo contra sentencias definitivas, laudos y resoluciones que pongan fin al juicio, así como de los recursos de revisión y queja."),
        35 to ArticleMeta("Competencia de los Juzgados de Distrito", "Competencia", "Los Juzgados de Distrito y los Tribunales Colegiados de Apelación conocen del amparo indirecto promovido contra normas generales, actos u omisiones de autoridades fuera de juicio o en juicio irreparable."),
        36 to ArticleMeta("Competencia Territorial en Amparo Indirecto", "Competencia", "Es competente el Juez de Distrito en cuya circunscripción territorial deba tener ejecución, trate de ejecutarse, se esté ejecutando o se haya ejecutado el acto reclamado."),
        37 to ArticleMeta("Competencia Concurrente y Auxiliar de Jueces Locales", "Competencia", "Los jueces de primera instancia locales podrán recibir la demanda de amparo y proveer sobre la suspensión de plano en auxilio de la justicia federal cuando en el lugar no haya Juez de Distrito."),
        38 to ArticleMeta("Conflictos Competenciales entre Órganos Jurisdiccionales", "Competencia", "Cuando un tribunal o juzgado federal se declare incompetente, remitirá de inmediato los autos al órgano que estime competente; si éste la rehúsa, se planteará el conflicto competencial."),
        39 to ArticleMeta("Substanciación del Conflicto de Competencia", "Competencia", "Los conflictos competenciales serán resueltos en el término de ocho días por el Tribunal Colegiado de Circuito que corresponda, sin admitir recurso alguno."),
        40 to ArticleMeta("Facultad de Atracción de la Suprema Corte", "Competencia", "El Pleno o las Salas de la Suprema Corte podrán ejercer la facultad de atracción de oficio o a solicitud fundada para conocer de juicios de amparo de especial interés y trascendencia jurídica."),
        41 to ArticleMeta("Causas Taxativas de Impedimento Judicial", "Impedimentos", "Los ministros, magistrados y jueces están impedidos para conocer de juicios en que tengan parentesco consanguíneo, interés personal directo o indirecto, o enemistad manifiesta con las partes."),
        42 to ArticleMeta("Planteamiento Oficioso del Impedimento", "Impedimentos", "El juzgador federal que se encuentre en alguna causal de impedimento tiene la obligación ineludible de manifestarla de oficio y abstenerse de dictar resoluciones en el juicio."),
        43 to ArticleMeta("Procedimiento de Recusación con Causa", "Impedimentos", "Las partes podrán recusar a los juzgadores federales por escrito bajo protesta de decir verdad, expresando la causa legal y ofreciendo las pruebas conducentes."),
        44 to ArticleMeta("Recusación de Magistrados de Circuito", "Impedimentos", "La recusación de magistrados de Circuito será calificada y resuelta por los demás integrantes del Tribunal Colegiado de Circuito respectivo."),
        45 to ArticleMeta("Recusación de Jueces de Distrito", "Impedimentos", "La recusación de jueces de Distrito será resuelta por el Tribunal Colegiado de Circuito de la circunscripción en trámite sumario dentro de los tres días siguientes."),
        46 to ArticleMeta("Trámite del Incidente de Recusación", "Impedimentos", "Admitida la recusación, se pedirá informe al juzgador recusado quien rendirá dentro de las veinticuatro horas siguientes, señalándose audiencia incidental."),
        47 to ArticleMeta("Medios de Prueba Admisibles en Recusación", "Impedimentos", "En el incidente de recusación sólo se admitirán pruebas documentales e inspección ocular de constancias judiciales, desechándose la testimonial de plano."),
        48 to ArticleMeta("Efectos de la Recusación Declarada Fundada", "Impedimentos", "Declarada fundada la recusación, el juzgador recusado quedará definitivamente separado del conocimiento del juicio y se remitirá el asunto al órgano que deba sustituirlo legalmente."),
        49 to ArticleMeta("Calificación de Mala Fe en Recusaciones", "Impedimentos", "Si la recusación se declara improcedente o infundada y se advierte temeridad o dolo procesal, se impondrá a la parte promovente una sanción económica en favor del erario."),
        50 to ArticleMeta("Imposición de Multas por Recusaciones Fícticias", "Impedimentos", "Las sanciones pecuniarias por recusaciones improcedentes se fijarán entre cincuenta y trescientas Unidades de Medida y Actualización (UMA) atendiendo a la gravedad."),
        51 to ArticleMeta("Excusa Forzosa de Jueces y Magistrados", "Impedimentos", "Los ministros, magistrados y jueces deben excusarse forzosamente tan pronto como conozcan la existencia del motivo de impedimento que afecte su imparcialidad."),
        52 to ArticleMeta("Órganos Competentes para Calificar Excusas", "Impedimentos", "Las excusas de jueces de Distrito las califica el Tribunal Colegiado; las de magistrados de Circuito los otros miembros del tribunal; y las de ministros las Salas o Pleno de la SCJN."),
        53 to ArticleMeta("Efectos de la Aceptación de la Excusa Judicial", "Impedimentos", "Calificada de legal la excusa, el titular o magistrado excusado se inhibirá del negocio y remitirá los autos inmediatamente al sustituto que prevea la Ley Orgánica del PJF."),
        54 to ArticleMeta("Reglas de Turno en Casos de Sustitución", "Impedimentos", "El Consejo de la Judicatura Federal determinará el sistema de turno aleatorio para la asignación de expedientes ante impedimentos o excusas calificadas de legales."),
        55 to ArticleMeta("Sustitución de Magistrados Impedidos", "Impedimentos", "En caso de impedimento de uno de los magistrados del Tribunal Colegiado, se llamará al secretario en funciones o al magistrado de otro tribunal para integrar el pleno."),
        56 to ArticleMeta("Prohibición de Recusar a Secretarios Judiciales", "Impedimentos", "Los secretarios y actuarios no son recusables pero tienen el deber de excusarse cuando concurra en ellos motivo legal de impedimento."),
        57 to ArticleMeta("Acumulación de Juicios de Amparo Conexos", "Acumulación", "Procede la acumulación de juicios de amparo pendientes ante el mismo o distintos Juzgados de Distrito cuando se reclamen actos conexos derivados del mismo procedimiento."),
        58 to ArticleMeta("Tramitación Sumaria de la Acumulación", "Acumulación", "La acumulación podrá promoverse de oficio o a petición de parte ante el juez que conozca del juicio promovido en primer lugar en el tiempo."),
        59 to ArticleMeta("Procedimiento Incidental de Acumulación", "Acumulación", "Promovida la acumulación, el juez dará vista a las partes por tres días y resolverá de plano dentro de las veinticuatro horas siguientes ordenando recabar los expedientes."),
        60 to ArticleMeta("Resolución y Efectos de la Acumulación Concedida", "Acumulación", "Decretada la acumulación, los juicios acumulados se resolverán en una sola sentencia en la misma audiencia constitucional para evitar fallos contradictorios."),
        61 to ArticleMeta("Causales Taxativas de Improcedencia del Amparo", "Improcedencia", "El juicio de amparo es improcedente: contra reformas y adiciones a la Constitución (I); actos de la SCJN (II); actos del Tribunal Electoral (III); actos de tribunales en cumplimiento de amparos (IV); actos consumados de modo irreparable (XVI); consentimiento expreso o tácito (XIII); cosa juzgada (XI); y demás supuestos de las fracciones I a XXIII."),
        62 to ArticleMeta("Examen Oficioso Obligatorio de la Improcedencia", "Improcedencia", "Las causas de improcedencia se analizarán de oficio por el órgano jurisdiccional de amparo en cualquier estado del juicio por constituir una cuestión de orden público preferente."),
        63 to ArticleMeta("Supuestos Legales de Sobreseimiento", "Sobreseimiento", "El sobreseimiento en el juicio de amparo procede cuando: I. El quejoso se desista expresamente; II. El quejoso no rinda pruebas de la existencia del acto; III. Quede probada la inexistencia del acto reclamado; IV. Durante el juicio sobrevenga alguna causal de improcedencia."),
        64 to ArticleMeta("Garantía de Audiencia ante Causal Superveniente", "Sobreseimiento", "Cuando el tribunal advierta de oficio una causa de improcedencia no alegada por las partes ni planteada en el informe justificado, dará vista a la quejosa por tres días para que manifieste lo que a su interés convenga."),
        65 to ArticleMeta("Efectos Procesales del Sobreseimiento Firme", "Sobreseimiento", "El sobreseimiento firme no prejuzga sobre la constitucionalidad o legalidad del acto reclamado, ni constituye cosa juzgada respecto del fondo sustantivo de la controversia."),
        66 to ArticleMeta("Incidentes de Previo y Especial Pronunciamiento", "Incidentes", "En los juicios de amparo sólo se sustanciarán por cuerda separada los incidentes que por su naturaleza requieran decisión judicial previa a la sentencia de fondo."),
        67 to ArticleMeta("Incidentes que Suspenden el Procedimiento Principal", "Incidentes", "Sólo suspenderán el procedimiento principal del amparo los incidentes de nulidad de notificaciones y reposición de autos extraviados."),
        68 to ArticleMeta("Pruebas y Sustanciación de Incidentes Innominados", "Incidentes", "Los incidentes que no tengan trámite especial se resolverán oyendo a las partes en una audiencia que se celebrará dentro de los tres días siguientes al auto admisorio."),
        69 to ArticleMeta("Sentencias Interlocutorias de Incidentes", "Incidentes", "Las determinaciones que decidan incidentes de especial pronunciamiento se pronunciarán en forma de sentencia interlocutoria debidamente fundada y motivada."),
        70 to ArticleMeta("Incidente de Reposición de Autos Extraviados", "Incidentes", "Cuando se extravíe o destruya un expediente o constancia de amparo, el secretario asentará certificación de inmediato y el juez ordenará abrir el incidente de reposición."),
        71 to ArticleMeta("Substanciación del Incidente de Reposición", "Incidentes", "El juez requerirá a las partes para que dentro de tres días presenten las copias fehacientes o electrónicas de los autos extraviados que obren en su poder."),
        72 to ArticleMeta("Declaratoria Judicial de Autos Repuestos", "Incidentes", "Cotejadas las copias y recibidas las certificaciones de la oficialía de partes, el juez declarará formalmente repuesto el expediente continuando el juicio de amparo."),
        73 to ArticleMeta("Sentencia de Amparo y Efecto Restitutorio Pleno", "Sentencias", "Las sentencias que se pronuncien en los juicios de amparo sólo se ocuparán de los individuos particulares o de las personas morales que lo hubieren solicitado, limitándose a ampararlos y protegerlos si procediere. La concesión restituirá al quejoso en el goce del derecho conculcado."),
        74 to ArticleMeta("Requisitos Formales y Contenido de la Sentencia", "Sentencias", "La sentencia debe contener: I. La fijación clara y precisa del acto reclamado; II. El análisis de las causas de improcedencia; III. La valoración de las pruebas rendidas; IV. Los fundamentos legales; V. Los efectos precisos de la concesión; y VI. Los puntos resolutivos."),
        75 to ArticleMeta("Apreciación del Acto tal como fue Probado", "Sentencias", "En las sentencias de amparo el acto reclamado se apreciará tal como aparezca probado ante la autoridad responsable, sin que puedan admitirse ni tomarse en consideración pruebas que no se hubiesen rendido ante dicha autoridad."),
        76 to ArticleMeta("Corrección Judicial de Preceptos Citados", "Sentencias", "El órgano jurisdiccional deberá corregir los errores que advierta en la cita de los preceptos constitucionales y legales invocados por el quejoso, con la finalidad de resolver la verdadera cuestión efectivamente planteada."),
        77 to ArticleMeta("Efectos Precisos de la Concesión del Amparo", "Sentencias", "Los efectos de la concesión serán: si el acto es de carácter positivo, restituir al quejoso en el pleno goce del derecho violado restableciendo las cosas al estado que guardaban; si es negativo, obligar a la autoridad a actuar respetando el derecho violado."),
        78 to ArticleMeta("Sentencia Concesoria contra Normas Generales", "Sentencias", "Cuando el acto reclamado sea una norma general, la sentencia protectora tendrá por efecto impedir que dicha norma se aplique en el presente y futuro al quejoso en tanto no sea reformada válidamente."),
        79 to ArticleMeta("Suplencia de la Deficiencia de la Queja", "Sentencias", "La autoridad que conozca del juicio de amparo suplirá la deficiencia de los conceptos de violación o agravios: en materia penal a favor del inculpado o víctima; agraria a ejidatarios; laboral a favor del trabajador; y en favor de menores o personas en vulnerabilidad."),
        80 to ArticleMeta("Medidas para Garantizar Cumplimiento de Sentencias", "Sentencias", "El órgano de amparo dictará de oficio las medidas pertinentes para exigir el exacto e inmediato cumplimiento de la ejecutoria de amparo por parte de las autoridades responsables."),
        81 to ArticleMeta("Procedencia Taxativa del Recurso de Revisión", "Recursos", "Procede el recurso de revisión: en amparo indirecto contra autos que desechen la demanda, resoluciones de suspensión definitiva, acuerdos de sobreseimiento y sentencias constitucionales; en amparo directo contra sentencias que resuelvan sobre constitucionalidad de normas."),
        82 to ArticleMeta("Recurso de Revisión Adhesiva", "Recursos", "La parte que obtuvo resolución favorable en el juicio de amparo podrá adherirse a la revisión interpuesta por otra de las partes dentro del plazo de cinco días hábiles contados a partir de que surta efectos la notificación de admisión."),
        83 to ArticleMeta("Competencia Originaria de la Suprema Corte en Revisión", "Recursos", "La Suprema Corte es competente para conocer del recurso de revisión contra sentencias dictadas en la audiencia constitucional cuando habiéndose impugnado normas generales subsista el problema de constitucionalidad."),
        84 to ArticleMeta("Competencia de Tribunales Colegiados en Revisión", "Recursos", "Los Tribunales Colegiados de Circuito son competentes para conocer de los recursos de revisión en los casos no reservados de manera exclusiva a la Suprema Corte de Justicia de la Nación."),
        85 to ArticleMeta("Atracción Extraordinaria de Recursos de Revisión", "Recursos", "La Suprema Corte de oficio o a solicitud fundada podrá conocer de recursos de revisión ante Tribunales Colegiados de Circuito cuando el asunto revista interés excepcional en materia de derechos humanos."),
        86 to ArticleMeta("Plazo de Diez Días para Interponer la Revisión", "Recursos", "El recurso de revisión se interpondrá por conducto del órgano jurisdiccional que haya dictado la resolución recurrida dentro del plazo de diez días hábiles contados desde el día siguiente a la notificación."),
        87 to ArticleMeta("Legitimación de las Autoridades Responsables para Recurrir", "Recursos", "Las autoridades responsables sólo podrán interponer el recurso de revisión contra sentencias que afecten directamente los actos emitidos por ellas dentro del ámbito estricto de sus facultades legales."),
        88 to ArticleMeta("Requisitos Formales del Escrito de Revisión", "Recursos", "El recurso de revisión se interpondrá por escrito en el que se expresarán los agravios que cause la resolución recurrida, acompañando copias del mismo para cada una de las partes en el juicio."),
        89 to ArticleMeta("Remisión del Expediente al Tribunal Colegiado", "Recursos", "Interpuesta la revisión y distribuidas las copias, el órgano que dictó el fallo remitirá el expediente original y el escrito de agravios dentro del término de tres días al Tribunal Colegiado competente."),
        90 to ArticleMeta("Admisión o Desechamiento del Recurso de Revisión", "Recursos", "El Presidente del Tribunal Colegiado resolverá en el auto inicial sobre la admisión o desechamiento del recurso de revisión interpuesto extemporáneamente o por parte no legitimada."),
        91 to ArticleMeta("Sustanciación y Procedimiento de la Revisión", "Recursos", "Admitido el recurso de revisión y notificado a las partes, el Presidente turnará el expediente al magistrado ponente para formular el proyecto de sentencia de alzada dentro de noventa días."),
        92 to ArticleMeta("Reglas Especiales de Resolución Colegiada", "Recursos", "Las resoluciones en los recursos de revisión se tomarán por unanimidad o mayoría de votos de los tres magistrados que integran el Tribunal Colegiado en sesión pública."),
        93 to ArticleMeta("Metodología de Análisis de Agravios en Alzada", "Recursos", "Al conocer de la revisión, el órgano revisor examinará primero las causales de improcedencia omitidas o sobrevenidas, revocará determinaciones infundadas y resolverá el fondo con plenitud de jurisdicción."),
        94 to ArticleMeta("Desistimiento Voluntario de la Revisión", "Recursos", "El recurrente podrá desistirse de la revisión antes de que se dicte resolución definitiva, debiendo ratificar el desistimiento ante la presencia judicial en tres días."),
        95 to ArticleMeta("Imposición de Multas en Recursos Improcedentes", "Recursos", "Se sancionará con multa económica a quien interponga el recurso de revisión con dolo evidente, temeridad procesal o con el exclusivo propósito de entorpecer el cumplimiento de la sentencia."),
        96 to ArticleMeta("Revisión ante la SCJN contra Amparo Directo", "Recursos", "Cuando se trate de revisión contra sentencia de amparo directo dictada por Tribunal Colegiado, la Suprema Corte examinará exclusivamente si entraña la fijación de un criterio de interés excepcional."),
        97 to ArticleMeta("Procedencia Taxativa del Recurso de Queja", "Recursos", "Procede el recurso de queja en amparo indirecto contra autos que desechen la demanda, acuerdos sobre suspensión provisional o definitiva, fianzas y contra resoluciones de cumplimiento sustituto; en directo contra omisiones de la responsable."),
        98 to ArticleMeta("Plazos para la Interposición del Recurso de Queja", "Recursos", "El plazo para interponer la queja es de cinco días hábiles. Excepción: de dos días hábiles cuando se trate de la resolución que conceda o niegue la suspensión de plano o provisional."),
        99 to ArticleMeta("Presentación de la Queja ante el Órgano Emisor", "Recursos", "El recurso de queja se interpondrá por escrito ante el órgano jurisdiccional que conozca del juicio de amparo, expresando los agravios que cause la determinación recurrida."),
        100 to ArticleMeta("Requisitos de Expresión de Agravios en la Queja", "Recursos", "El escrito de queja debe expresar con claridad los agravios concretos ocasionados y exhibir copias para correr traslado al Ministerio Público y a las partes interesadas."),
        101 to ArticleMeta("Trámite y Resolución Sumaria de la Queja", "Recursos", "El recurso de queja se resolverá en el plazo de cuarenta días hábiles por el Tribunal Colegiado de Circuito; si se trata de suspensión provisional o de plano, se resolverá en un plazo perentorio de 48 horas."),
        102 to ArticleMeta("Efectos Procesales de la Queja Fundada", "Recursos", "Declarada fundada la queja, el Tribunal Colegiado dictará de inmediato la resolución que corresponda sustituyendo la omisión o irregularidad del órgano a quo."),
        103 to ArticleMeta("Procedencia del Recurso de Reclamación", "Recursos", "El recurso de reclamación es procedente contra los acuerdos de trámite dictados por el Presidente de la Suprema Corte de Justicia o por los presidentes de las Salas o de los Tribunales Colegiados."),
        104 to ArticleMeta("Plazo Improrrogable de Tres Días para Reclamar", "Recursos", "El recurso de reclamación se interpondrá dentro de los tres días hábiles siguientes al en que surta efectos la notificación de la resolución o acuerdo impugnado."),
        105 to ArticleMeta("Trámite y Resolución de la Reclamación en Diez Días", "Recursos", "Radicado el recurso de reclamación, se turnará al ministro o magistrado ponente respectivo para que dentro de los diez días siguientes formule proyecto y se dicte resolución."),
        106 to ArticleMeta("Efectos Obligatorios de la Reclamación Fundada", "Recursos", "La resolución que declare fundada la reclamación revocará el auto recurrido y obligará al presidente del órgano a dictar el proveído legal que en derecho corresponda."),
        107 to ArticleMeta("Procedencia del Juicio de Amparo Indirecto", "Amparo Indirecto", "El amparo indirecto procede: I. Contra normas generales; II. Contra actos u omisiones que provengan de autoridades distintas de los tribunales judiciales; III. Contra actos en juicio de imposible reparación que afecten derechos sustantivos; IV. Contra actos dictados fuera de juicio o después de concluido; V. Contra actos que afecten a personas extrañas al juicio; VI. Contra actos de remate."),
        108 to ArticleMeta("Requisitos de la Demanda de Amparo Indirecto", "Amparo Indirecto", "La demanda de amparo indirecto deberá formularse por escrito expresando: nombre del quejoso, tercero interesado, autoridades responsables, norma general o acto reclamado, antecedentes bajo protesta y conceptos de violación."),
        109 to ArticleMeta("Formas de Presentación: Escrita y Digital", "Amparo Indirecto", "La demanda podrá presentarse por escrito impreso o mediante documento electrónico utilizando la firma electrónica certificada en el Portal del Poder Judicial de la Federación."),
        110 to ArticleMeta("Copias de Traslado de la Demanda para las Partes", "Amparo Indirecto", "El quejoso deberá acompañar copias de la demanda para cada una de las autoridades responsables, tercero interesado, Ministerio Público y dos para el incidente de suspensión si se solicita."),
        111 to ArticleMeta("Ampliación de la Demanda de Amparo Indirecto", "Amparo Indirecto", "Procede ampliar la demanda cuando no hayan transcurrido los plazos legales o cuando del informe justificado aparezcan nuevos actos estrechamente vinculados con los reclamados inicialmente."),
        112 to ArticleMeta("Término de 24 Horas para Acordar la Demanda", "Amparo Indirecto", "Recibida la demanda de amparo, el Juez de Distrito deberá resolver en el plazo inaplazable de veinticuatro horas si la admite, previene al quejoso o la desecha de plano."),
        113 to ArticleMeta("Desechamiento de Plano por Causal Manifiesta", "Amparo Indirecto", "El Juez de Distrito desechará de plano la demanda de amparo cuando encuentre un motivo manifiesto e indudable de improcedencia que no requiera sustanciación posterior."),
        114 to ArticleMeta("Auto de Prevención y Aclaración de la Demanda", "Amparo Indirecto", "Si hubiere irregularidades en el escrito de demanda, falten copias o no se precisen los actos reclamados, el juez prevendrá al quejoso para que aclare dentro del término de cinco días hábiles."),
        115 to ArticleMeta("Auto Admisorio, Informe Justificado y Audiencia", "Amparo Indirecto", "Admitida la demanda, el juez requerirá informe justificado a las autoridades responsables en el plazo de quince días y fijará fecha y hora para la audiencia constitucional dentro de los treinta días siguientes."),
        116 to ArticleMeta("Obligación de Señalar Domicilio y Correo Electrónico", "Amparo Indirecto", "Las autoridades y terceros interesados deben señalar domicilio y correo oficial para la práctica de notificaciones judiciales desde su primera comparecencia."),
        117 to ArticleMeta("Contenido y Plazo del Informe con Justificación", "Amparo Indirecto", "Las autoridades responsables rendirán su informe justificado dentro de quince días manifestando si es cierto o no el acto reclamado, las razones legales que lo funden y acompañando constancias certificadas."),
        118 to ArticleMeta("Informes de Autoridades Coadyuvantes", "Amparo Indirecto", "Las autoridades que tengan intervención complementaria o coadyuvante rendirán informes dentro del plazo fijado remitiendo los expedientes administrativos originales."),
        119 to ArticleMeta("Ofrecimiento y Desahogo de Medios Probatorios", "Amparo Indirecto", "En amparo indirecto son admisibles toda clase de pruebas excepto la confesional por posiciones. La testimonial, pericial e inspección ocular deberán ofrecerse con cinco días hábiles de anticipación a la audiencia."),
        120 to ArticleMeta("Admisión de Pruebas Documentales e Informes", "Amparo Indirecto", "Los documentos deberán presentarse con anterioridad a la audiencia constitucional; las partes pueden solicitar al juez requerir copias a archivos oficiales si les fueron negadas."),
        121 to ArticleMeta("Procedimiento de Objeción de Documentos", "Amparo Indirecto", "Cualquiera de las partes podrá objetar de falsos los documentos presentados en el juicio dentro del plazo de tres días contados a partir de su vista procesal."),
        122 to ArticleMeta("Incidente de Autenticidad en Audiencia Constitucional", "Amparo Indirecto", "Planteada la objeción documental, el juez abrirá incidente sumario en la misma audiencia constitucional desahogando peritajes y resolviendo sobre su validez probatoria."),
        123 to ArticleMeta("Práctica Judicial de Inspección Ocular", "Amparo Indirecto", "La prueba de inspección judicial se practicará directamente por el Juez de Distrito o por el secretario que comisione al efecto levantando acta circunstanciada."),
        124 to ArticleMeta("Celebración de la Audiencia Constitucional", "Amparo Indirecto", "La audiencia constitucional es pública y concentrada: en ella se abrirá el período de desahogo de pruebas, se recibirán los alegatos por escrito, el pedimento del MP y se dictará la sentencia definitiva."),
        125 to ArticleMeta("Formas de la Suspensión del Acto Reclamado", "Suspensión", "La suspensión del acto reclamado en el juicio de amparo indirecto se decretará de oficio o a petición de parte agraviada con efectos provisionales o definitivos."),
        126 to ArticleMeta("Suspensión de Oficio y de Plano Inmediata", "Suspensión", "La suspensión se concederá de oficio y de plano cuando se trate de actos que importen peligro de privación de la vida, ataques a la libertad personal fuera de procedimiento, incomunicación o destierro."),
        127 to ArticleMeta("Suspensión Oficiosa en Materia Agraria y Penal", "Suspensión", "Procede decretar la suspensión oficiosa en materia agraria en defensa de tierras ejidales y en materia penal respecto a la libertad física y seguridad del quejoso."),
        128 to ArticleMeta("Requisitos de la Suspensión a Petición de Parte", "Suspensión", "Con excepción de los casos de oficio, la suspensión se decretará cuando: I. La solicite el quejoso; y II. No se siga perjuicio al interés social ni se contravengan disposiciones de orden público."),
        129 to ArticleMeta("Catálogo de Casos en Perjuicio del Interés Social", "Suspensión", "Se considera perjuicio al interés social si la suspensión: perpetúa centros de vicio, producción de drogas ilícitas, afecta la economía nacional o el abasto de servicios públicos esenciales."),
        130 to ArticleMeta("Ponderación de la Apariencia del Buen Derecho", "Suspensión", "El juzgador realizará un juicio de ponderación entre la apariencia del buen derecho (fumus boni iuris) y el interés social para determinar la procedencia de la medida suspensiva."),
        131 to ArticleMeta("Fijación de Garantía y Fianza de Suspensión", "Suspensión", "Cuando la suspensión pueda ocasionar daño o perjuicio a un tercero interesado, surtirá efectos si el quejoso otorga garantía bastante para reparar el daño que se causare."),
        132 to ArticleMeta("Exigibilidad de Garantía para Surtimiento de Efectos", "Suspensión", "La garantía fijada por el juez para amparar daños y perjuicios a terceros deberá otorgarse dentro de los cinco días siguientes bajo apercibimiento de dejar sin efectos la medida."),
        133 to ArticleMeta("Efectividad y Cancelación de la Garantía", "Suspensión", "La garantía se hará efectiva ante el juez si se niega el amparo definitivo y se acreditan daños, o se cancelará si se concede la protección constitucional de la justicia de la Unión."),
        134 to ArticleMeta("Contragarantía del Tercero Interesado", "Suspensión", "La suspensión otorgada quedará sin efecto si el tercero interesado otorga contragarantía bastante para restituir las cosas al estado que guardaban y reparar los perjuicios causados al quejoso."),
        135 to ArticleMeta("Suspensión contra Cobros Fiscales y Contribuciones", "Suspensión", "Tratándose del cobro de contribuciones y créditos fiscales, la suspensión surtirá efectos si se deposita el importe de la suma controvertida ante la Tesorería de la Federación o autoridad recaudadora."),
        136 to ArticleMeta("Suspensión en Materia Penal y Libertad Personal", "Suspensión", "Cuando el acto reclamado afecte la libertad personal, la suspensión tendrá por efecto que el quejoso quede a disposición del órgano de amparo en cuanto a su libertad y ante el juez penal para el proceso."),
        137 to ArticleMeta("Reglas de Caución para la Libertad en Amparo Penal", "Suspensión", "El juez de amparo fijará al quejoso caución económica o medidas cautelares indispensables para asegurar que no se sustraiga de la acción de la justicia penal ordinaria."),
        138 to ArticleMeta("Auto Inicial y Audiencia Incidental de Suspensión", "Suspensión", "Promovida la suspensión a petición, el juez acordará en 24 horas concediendo o negando la suspensión provisional y fijará fecha para la audiencia incidental dentro de los cinco días siguientes."),
        139 to ArticleMeta("Vigencia de la Medida Cautelar Provisional", "Suspensión", "La suspensión provisional surtirá efectos desde que se pronuncie el auto inicial hasta que se notifique formalmente a las partes la resolución interlocutoria sobre la suspensión definitiva."),
        140 to ArticleMeta("Informe Previo de las Autoridades Responsables (48 Horas)", "Suspensión", "Las autoridades responsables deberán rendir su informe previo dentro del término improrrogable de cuarenta y ocho horas manifestando la certeza o inexistencia de los actos reclamados."),
        141 to ArticleMeta("Pruebas Admisibles en el Incidente Suspensivo", "Suspensión", "En el incidente de suspensión sólo serán admisibles las pruebas documentales y de inspección ocular, pudiéndose presentar directamente hasta el momento de celebrarse la audiencia."),
        142 to ArticleMeta("Desahogo Concentrado de la Audiencia Incidental", "Suspensión", "La audiencia incidental se celebrará con las pruebas y alegatos presentados; el juez resolverá de inmediato dictando sentencia interlocutoria fundada y motivada."),
        143 to ArticleMeta("Modificación o Revocación por Hecho Superveniente", "Suspensión", "La resolución que conceda o niegue la suspensión definitiva podrá modificarse o revocarse en cualquier momento cuando sobrevenga un hecho nuevo que altere las bases de su otorgamiento."),
        144 to ArticleMeta("Sentencia Interlocutoria sobre Suspensión Definitiva", "Suspensión", "En la sentencia interlocutoria el juez valorará la existencia del acto, el informe previo, la apariencia del buen derecho y el orden público, concediendo o negando la medida definitiva."),
        145 to ArticleMeta("Preservación de la Materia Litigiosa del Amparo", "Suspensión", "El objeto primordial de la medida suspensiva es evitar que se consumen irreparablemente los actos reclamados y mantener viva la materia de la sentencia constitucional de amparo."),
        146 to ArticleMeta("Medidas Precautorias sobre Personas y Bienes", "Suspensión", "El juzgador está facultado para decretar medidas cautelares urgentes dirigidas a asegurar la integridad personal de las partes o el depósito seguro de los bienes muebles afectados."),
        147 to ArticleMeta("Medidas Cautelares Positivas y Restitutorias", "Suspensión", "Atendiendo a la naturaleza del acto, la suspensión podrá tener efectos conservativos o de tutela anticipada provisional para restablecer el derecho violado en tanto se resuelve el fondo."),
        148 to ArticleMeta("Suspensión contra Normas Generales Impugnadas", "Suspensión", "En amparo contra normas generales, la suspensión no podrá tener efectos generales abrogatorios pero paralizará de inmediato la aplicación concreta de la norma respecto del quejoso."),
        149 to ArticleMeta("Suspensión contra Procedimientos de Remate Judicial", "Suspensión", "En procedimientos de remate judicial, la suspensión permitirá que el procedimiento continúe hasta antes de verificarse la adjudicación o entrega material definitiva de los bienes."),
        150 to ArticleMeta("Efectos Suspensivos en Procesos de Extradición", "Suspensión", "En procedimientos de extradición internacional, la suspensión tendrá como efecto exclusivo que el reclamado no sea entregado al Estado requirente hasta que cause ejecutoria el amparo."),
        151 to ArticleMeta("Suspensión en Actos Agrarios Colectivos", "Suspensión", "Las medidas cautelares en materia agraria se concederán de oficio y sin fianza cuando afecten los derechos de ejidos, comunidades indígenas y parcelas comunales."),
        152 to ArticleMeta("Reglas Cautelares ante Tribunales del Fuero Militar", "Suspensión", "Cuando el acto privativo provenga de autoridades castrenses, el juez de amparo decretará la suspensión para que el detenido quede a disposición de la justicia federal civil ordinaria."),
        153 to ArticleMeta("Suspensión en Procedimientos Administrativos de Sanción", "Suspensión", "En procedimientos sancionadores administrativos, la suspensión evitará la ejecución de multas, clausuras o inhabilitaciones que afecten la subsistencia de la parte quejosa."),
        154 to ArticleMeta("Verificación Judicial de Garantías Otorgadas", "Suspensión", "El juez revisará periódicamente que las pólizas de fianza o depósitos en efectivo otorgados conserven su valor adquisitivo y vigencia frente a la depreciación monetaria."),
        155 to ArticleMeta("Resolución Incidental de Aumento de Fianza", "Suspensión", "A solicitud justificada del tercero interesado, el juzgador podrá incrementar la fianza de suspensión si los daños causados por el retardo superan el monto garantizado inicialmente."),
        156 to ArticleMeta("Desobediencia de Autoridades a la Medida Cautelar", "Suspensión", "Cualquier desacato u omisión de las autoridades responsables respecto de la orden suspensiva implicará el inicio del procedimiento de responsabilidad penal y denuncia ministerial."),
        157 to ArticleMeta("Efectos Cautelares en Materia Laboral y Huelgas", "Suspensión", "En conflictos colectivos de trabajo la suspensión no impedirá el ejercicio lícito del derecho constitucional de huelga ni la subsistencia de los salarios devengados."),
        158 to ArticleMeta("Suspensión contra Órdenes de Clausura Mercantil", "Suspensión", "Tratándose de clausura definitiva de establecimientos mercantiles, la suspensión procederá si el negocio cuenta con licencias y no genera riesgo grave a la seguridad de la comunidad."),
        159 to ArticleMeta("Medidas Tutelares en Menores y Familiares", "Suspensión", "En asuntos que involucren menores, alimentos y custodia, la suspensión velará preferentemente por el interés superior de la niñez garantizando la pensión alimenticia indispensable."),
        160 to ArticleMeta("Efectos Inmediatos de la Notificación Cautelar", "Suspensión", "La resolución de suspensión surtirá efectos inmediatamente desde el momento en que se dicte, debiendo comunicarse por vía electrónica, telégrafo o mensaje urgente a las responsables."),
        161 to ArticleMeta("Suspensión en Materia de Extinción de Dominio", "Suspensión", "En juicios de extinción de dominio la medida suspensiva evitará la subasta o venta anticipada de los bienes asegurados antes de dictarse sentencia judicial firme."),
        162 to ArticleMeta("Suspensión de Actos de Desposesión Inmobiliaria", "Suspensión", "Cuando el acto reclamado implique el desalojo forzoso o lanzamiento de casa habitación, la suspensión protegerá la posesión del quejoso en tanto se examine la legalidad del título."),
        163 to ArticleMeta("Reglas de Fianza en Amparo Ambiental", "Suspensión", "En juicios de amparo ambiental promovidos por comunidades no se exigirá fianza alguna para otorgar la suspensión contra proyectos que causen daño irreversible a los ecosistemas."),
        164 to ArticleMeta("Suspensión frente a Bloqueo de Cuentas Bancarias", "Suspensión", "Procederá conceder la suspensión contra el congelamiento administrativo de cuentas bancarias ordenado por la UIF cuando se trate de fondos indispensables para alimentos o nóminas."),
        165 to ArticleMeta("Suspensión de Actos Notariales y Registrales", "Suspensión", "La medida cautelar suspenderá inscripciones en el Registro Público de la Propiedad cuando puedan generar afectaciones a terceros de buena fe o transmitir derechos controvertidos."),
        166 to ArticleMeta("Suspensión de Órdenes de Aprehensión", "Suspensión", "Tratándose de delitos de prisión preventiva oficiosa la suspensión no impedirá la detención física pero el quejoso quedará a disposición del juez de amparo en su lugar de reclusión."),
        167 to ArticleMeta("Suspensión de Delitos sin Prisión Preventiva Forzosa", "Suspensión", "Si el delito imputado no amerita prisión preventiva oficiosa, la suspensión evitará la privación de la libertad mediante comparecencia periódica y fianza económica ante el Juez de Control."),
        168 to ArticleMeta("Incidente de Modificación de Medidas Cautelares", "Suspensión", "Las partes podrán solicitar en cualquier momento la revisión incidental de la suspensión si cambian las condiciones de hecho o las normativas bajo las cuales fue concedida."),
        169 to ArticleMeta("Ejecución Inmediata de la Suspensión", "Suspensión", "Los actuarios judiciales y la fuerza pública auxiliar ejecutarán de inmediato las determinaciones de suspensión de plano y definitiva sin admitir dilación alguna."),
        170 to ArticleMeta("Procedencia del Juicio de Amparo Directo", "Amparo Directo", "El amparo directo procede ante los Tribunales Colegiados de Circuito: I. Contra sentencias definitivas, laudos y resoluciones que pongan fin al juicio dictadas por tribunales judiciales, administrativos, agrarios o del trabajo; II. Contra sentencias que resuelvan violaciones de fondo o procedimentales."),
        171 to ArticleMeta("Agotamiento Obligatorio de Recursos y Violaciones Procesales", "Amparo Directo", "Al reclamarse la sentencia definitiva o laudo deberán hacerse valer las violaciones a las leyes del procedimiento, siempre que el quejoso las haya impugnado en el curso del juicio ordinario mediante los recursos procedentes."),
        172 to ArticleMeta("Catálogo de Violaciones Procesales Civiles y Laborales", "Amparo Directo", "En materia civil, administrativa o laboral se violan las leyes del procedimiento: si no se emplaza al quejoso; si se le niegan pruebas legalmente admisibles; o si se desahogan diligencias sin su presencia."),
        173 to ArticleMeta("Catálogo de Violaciones Procesales en Materia Penal", "Amparo Directo", "En los juicios penales se considerará violado el procedimiento: si no se le hace saber al imputado el motivo del proceso; si se le niega asistencia de defensor letrado; o si se admiten pruebas ilícitas obtenidas bajo tortura."),
        174 to ArticleMeta("Demostración de Trascendencia al Fallo", "Amparo Directo", "El quejoso deberá precisar en su demanda de amparo directo en qué consistió la infracción procesal y cómo trascendió al resultado de la sentencia definitiva o laudo impugnado."),
        175 to ArticleMeta("Requisitos de la Demanda de Amparo Directo", "Amparo Directo", "La demanda deberá formularse por escrito expresando: nombre del quejoso, tercero interesado, autoridad responsable que dictó el fallo, sentencia impugnada, fecha de notificación y conceptos de violación."),
        176 to ArticleMeta("Presentación ante la Autoridad Responsable Emisora", "Amparo Directo", "La demanda de amparo directo se presentará por conducto de la autoridad responsable que emitió la sentencia definitiva o laudo, so pena de desecharse si se promueve ante órgano incompetente."),
        177 to ArticleMeta("Responsabilidad de la Autoridad por Retardo Indebido", "Amparo Directo", "Si la autoridad responsable retarda indebidamente la remisión de la demanda o autos al Tribunal Colegiado, incurrirá en responsabilidad administrativa y se le impondrá sanción económica."),
        178 to ArticleMeta("Certificación, Emplazamiento y Remisión en Cinco Días", "Amparo Directo", "La responsable certificará al pie de la demanda la fecha de notificación, emplazará a los terceros interesados, rendirá su informe con justificación y remitirá los autos en cinco días al Tribunal Colegiado."),
        179 to ArticleMeta("Calificación de Admisibilidad por el Presidente del TCC", "Amparo Directo", "El Presidente del Tribunal Colegiado de Circuito examinará la demanda y dentro del plazo de tres días la admitirá, prevendrá al quejoso si presenta irregularidades, o la desechará si es improcedente."),
        180 to ArticleMeta("Aclaración de la Demanda de Amparo Directo", "Amparo Directo", "Si hubiere irregularidades o no se hubiesen exhibido copias bastantes, el Presidente prevendrá al promovente para que subsane los defectos dentro del plazo de cinco días hábiles."),
        181 to ArticleMeta("Notificación de Admisión y Alegatos o Amparo Adhesivo", "Amparo Directo", "Admitida la demanda, se notificará a las partes para que dentro del plazo improrrogable de quince días hábiles formulen sus alegatos por escrito o promuevan amparo directo adhesivo."),
        182 to ArticleMeta("Juicio de Amparo Directo Adhesivo", "Amparo Directo", "La parte que haya obtenido sentencia favorable en el juicio ordinario podrá promover amparo adhesivo para fortalecer las consideraciones del fallo o impugnar violaciones procesales que le perjudiquen."),
        183 to ArticleMeta("Turno al Magistrado Ponente para Proyecto", "Amparo Directo", "Concluido el plazo de quince días para alegatos o amparo adhesivo, el Presidente del Tribunal Colegiado turnará de inmediato el expediente a uno de los magistrados para elaborar el proyecto de resolución."),
        184 to ArticleMeta("Plazo de Noventa Días para Emisión de Proyecto", "Amparo Directo", "El magistrado ponente dispondrá de un plazo de noventa días hábiles para formular y registrar el proyecto de sentencia que será sometido a la discusión plenaria del tribunal."),
        185 to ArticleMeta("Publicación Previa de Proyectos de Constitucionalidad", "Amparo Directo", "Los proyectos de sentencia en que se decida sobre la constitucionalidad o convencionalidad de normas generales se publicarán con al menos tres días de anticipación a la sesión pública de resolución."),
        186 to ArticleMeta("Discusión y Votación Pública de Sentencias", "Amparo Directo", "Las sesiones de los Tribunales Colegiados de Circuito para resolver juicios de amparo directo serán públicas y transmitidas por medios electrónicos salvo reserva legal estricta."),
        187 to ArticleMeta("Sentencia Colegiada y Votos Particulares", "Amparo Directo", "Las resoluciones se tomarán por unanimidad o mayoría de votos; el magistrado que no estuviere conforme con el sentido del fallo formulará su voto particular o concurrente."),
        188 to ArticleMeta("Plazo de Diez Días para Engrose de la Sentencia", "Amparo Directo", "Aprobado el proyecto en sesión de pleno, el engrose formal de la ejecutoria de amparo directo se redactará y firmará dentro de los diez días hábiles siguientes."),
        189 to ArticleMeta("Metodología: Principio de Mayor Beneficio Jurídico", "Amparo Directo", "El Tribunal Colegiado resolverá privilegiando el examen de los conceptos de violación de fondo que conduzcan a declarar la inconstitucionalidad total del acto o la absolución del quejoso."),
        190 to ArticleMeta("Suspensión en Amparo Directo por la Responsable", "Amparo Directo", "La autoridad responsable decidirá sobre la suspensión de la ejecución de la sentencia definitiva dentro de veinticuatro horas, exigiendo fianza si pudiere causar daños a terceros."),
        191 to ArticleMeta("Medidas Cautelares Dictadas por la Autoridad Responsable", "Amparo Directo", "En materia penal la presentación de la demanda suspenderá de plano la ejecución de sentencias privativas de libertad; en materia civil la fianza garantizará las prestaciones devengadas."),
        192 to ArticleMeta("Cumplimiento de Sentencias Protectoras Ejecutorias", "Cumplimiento", "Las ejecutorias de amparo deben ser puntualmente cumplidas. Tan pronto cause ejecutoria, el órgano jurisdiccional requerirá a la autoridad responsable para que cumpla en el plazo de tres días hábiles."),
        193 to ArticleMeta("Procedimiento de Inejecución ante Tribunal Colegiado y SCJN", "Cumplimiento", "Si la autoridad no cumple en el plazo fijado, el tribunal remitirá el expediente a la Suprema Corte de Justicia de la Nación para que tramite la separación del cargo y consignación penal de la autoridad renuente."),
        194 to ArticleMeta("Efectos del Cumplimiento Extemporáneo", "Cumplimiento", "El cumplimiento extemporáneo de la ejecutoria de amparo no exime de la sanción económica ni de la responsabilidad penal en que hubieren incurrido los servidores públicos responsables."),
        195 to ArticleMeta("Archivo Definitivo del Expediente de Amparo", "Cumplimiento", "El expediente judicial sólo podrá archivarse definitivamente una vez que se haya verificado el cabal, íntegro y exacto cumplimiento de la sentencia protectora sin exceso ni defecto."),
        196 to ArticleMeta("Calificación Judicial del Cumplimiento de Sentencia", "Cumplimiento", "Rendido el informe de cumplimiento por la autoridad, el juez dará vista al quejoso y al tercero interesado por tres días y resolverá mediante auto si la sentencia está cabalmente cumplida."),
        197 to ArticleMeta("Requerimiento Coactivo a Superiores Jerárquicos", "Cumplimiento", "El requerimiento de cumplimiento judicial se notificará simultáneamente al superior jerárquico de la autoridad responsable bajo apercibimiento de destitución si no la conmina a acatar el fallo."),
        198 to ArticleMeta("Sustanciación del Incidente de Inejecución", "Cumplimiento", "El Tribunal Colegiado de Circuito sustanciará el incidente de inejecución de sentencia; si subsiste la contumacia emitirá dictamen proponiendo a la Suprema Corte la separación del cargo público."),
        199 to ArticleMeta("Incidente de Repetición del Acto Reclamado", "Cumplimiento", "La repetición del acto reclamado podrá ser denunciada por la parte interesada ante el órgano de amparo dentro del plazo de quince días contados a partir de su conocimiento formal."),
        200 to ArticleMeta("Sanción Penal por Repetición del Acto Inconstitucional", "Cumplimiento", "Declarada la repetición del acto reclamado por la Suprema Corte, la autoridad contumaz será inmediatamente separada de su empleo y consignada ante el Juez de Distrito por desacato constitucional."),
        201 to ArticleMeta("Procedencia del Recurso de Inconformidad", "Cumplimiento", "El recurso de inconformidad procede contra determinaciones que: I. Tengan por cumplida la ejecutoria de amparo; II. Declaren que existe imposibilidad material o jurídica para cumplirla; III. Declaren infundada o improcedente la repetición del acto; IV. Resuelvan la denuncia de exceso o defecto en cumplimiento."),
        202 to ArticleMeta("Plazo de Quince Días para la Inconformidad", "Cumplimiento", "El recurso de inconformidad podrá interponerse por el quejoso o tercero dentro del plazo de quince días hábiles siguientes al en que surta efectos la notificación de la resolución recurrida."),
        203 to ArticleMeta("Competencia para Resolver el Recurso de Inconformidad", "Cumplimiento", "Los Tribunales Colegiados de Circuito y la Suprema Corte de Justicia de la Nación resolverán la inconformidad examinando oficiosamente si la ejecutoria de amparo fue cumplida sin excesos ni defectos."),
        204 to ArticleMeta("Denuncia por Exceso o Defecto en Medida Cautelar", "Cumplimiento", "La violación o el cumplimiento con exceso o defecto a la suspensión de plano o definitiva se denunciará ante el órgano de amparo, resolviéndose en audiencia sumaria en cinco días."),
        205 to ArticleMeta("Cumplimiento Sustituto de la Sentencia Protectora", "Cumplimiento", "El cumplimiento sustituto se decretará de oficio o a petición de parte cuando la ejecución del fallo afecte gravemente a la sociedad en mayor proporción que los beneficios que obtendría el quejoso."),
        206 to ArticleMeta("Denuncia de Contradicción de Criterios", "Jurisprudencia", "La contradicción de criterios entre Tribunales Colegiados o Plenos Regionales podrá denunciarse por los jueces, magistrados, fiscales o partes procesales para unificar la jurisprudencia."),
        207 to ArticleMeta("Trámite Incidental de Cumplimiento Sustituto", "Cumplimiento", "El incidente de cumplimiento sustituto se tramitará ante el tribunal de origen desahogándose peritajes para fijar el valor pecuniario de los daños y perjuicios a indemnizar."),
        208 to ArticleMeta("Cuantificación Judicial de la Indemnización Sustituta", "Cumplimiento", "Fijada la indemnización por el juez, se ordenará su pago inmediato por la autoridad responsable con cargo a su presupuesto institucional en el término de diez días."),
        209 to ArticleMeta("Efectos Extintivos del Pago Indemnizatorio Sustituto", "Cumplimiento", "Acreditado el pago de la indemnización fijada a favor del quejoso, el juez declarará formalmente cumplida la ejecutoria de amparo y ordenará el archivo del asunto."),
        210 to ArticleMeta("Declaratoria de Imposibilidad Material o Jurídica", "Cumplimiento", "Cuando el cumplimiento resulte material o jurídicamente inviable por desaparición de la cosa o cambio irreversible de la situación, el tribunal lo declarará abriendo la vía sustituta."),
        211 to ArticleMeta("Reglas Accesorias de Cumplimiento de Sentencias", "Cumplimiento", "Las autoridades que intervengan en la ejecución de la sentencia de amparo responderán solidariamente del acatamiento de las órdenes emitidas por los órganos jurisdiccionales."),
        212 to ArticleMeta("Efectos de la Muerte de la Autoridad Responsable", "Cumplimiento", "El cambio de titular o la muerte del servidor público que emitió el acto no suspenderá en ningún caso la obligación del órgano estatal sucesor de cumplir la ejecutoria protectora."),
        213 to ArticleMeta("Responsabilidad Civil por Retardo Malicioso", "Cumplimiento", "El quejoso podrá demandar por la vía civil los daños y perjuicios suplementarios ocasionados por la contumacia o retardo doloso de los servidores públicos en cumplir el fallo."),
        214 to ArticleMeta("Disposiciones Especiales en Cumplimiento Colectivo", "Cumplimiento", "En amparos promovidos en defensa de intereses difusos o derechos colectivos, el juez fijará cronogramas públicos de seguimiento con verificación bimestral obligatoria."),
        215 to ArticleMeta("Mecanismos de Creación de Jurisprudencia", "Jurisprudencia", "La jurisprudencia se establece: I. Por precedentes obligatorios; II. Por reiteración de criterios; y III. Por contradicción de criterios entre órganos del Poder Judicial de la Federación."),
        216 to ArticleMeta("Jurisprudencia por Precedentes de la SCJN", "Jurisprudencia", "La jurisprudencia por precedentes obligatorios se establece por la Suprema Corte de Justicia de la Nación cuando resuelve asuntos de su competencia con las mayorías calificadas de ley."),
        217 to ArticleMeta("Obligatoriedad Erga Omnes de la Jurisprudencia", "Jurisprudencia", "La jurisprudencia que establezca la Suprema Corte es obligatoria para todas las autoridades jurisdiccionales de la Federación, de las entidades federativas y de los tribunales militares."),
        218 to ArticleMeta("Estructura y Requisitos de las Tesis Jurisprudenciales", "Jurisprudencia", "Las tesis de jurisprudencia deberán contener: título, subtítulo con el tema jurídico, texto con los hechos relevantes y el criterio jurídico vinculante, y datos de identificación del precedente."),
        219 to ArticleMeta("Difusión en el Semanario Judicial de la Federación", "Jurisprudencia", "Las tesis de jurisprudencia y precedentes obligatorios se publicarán semanalmente los viernes en el Semanario Judicial de la Federación para surtir plenos efectos obligatorios."),
        220 to ArticleMeta("Sistematización y Compilación de Tesis Jurisprudenciales", "Jurisprudencia", "La Coordinación de Compilación y Sistematización de Tesis de la Suprema Corte organizará los registros, índices temáticos y gacetas electrónicas del sistema jurisprudencial."),
        221 to ArticleMeta("Solicitud de Aclaración de Criterios Jurisprudenciales", "Jurisprudencia", "Las Salas de la SCJN o los Tribunales Colegiados de Circuito podrán solicitar la aclaración de una tesis de jurisprudencia cuando existan dudas sobre su interpretación u obligatoriedad."),
        222 to ArticleMeta("Mayoría de Ocho Votos del Pleno de la SCJN", "Jurisprudencia", "Las razones que justifiquen las decisiones contenidas en las sentencias dictadas por el Pleno de la Suprema Corte constituyen precedentes obligatorios al ser aprobadas por mayoría de al menos ocho votos."),
        223 to ArticleMeta("Mayoría de Cuatro Votos de las Salas de la SCJN", "Jurisprudencia", "Las consideraciones contenidas en las sentencias de las Salas de la Suprema Corte constituyen precedentes obligatorios cuando fueren aprobadas por mayoría de al menos cuatro votos."),
        224 to ArticleMeta("Jurisprudencia por Reiteración de Tribunales Colegiados", "Jurisprudencia", "La jurisprudencia por reiteración de los Tribunales Colegiados se establece al sustentarse un mismo criterio en cinco sentencias no interrumpidas por otra en contrario y aprobadas por unanimidad."),
        225 to ArticleMeta("Jurisprudencia por Contradicción de Criterios", "Jurisprudencia", "La jurisprudencia por contradicción de criterios se establece al resolver los diferendos sostenidos entre Tribunales Colegiados de Circuito o entre Plenos Regionales."),
        226 to ArticleMeta("Competencia para Dirimir Contradicciones", "Jurisprudencia", "El Pleno y Salas de la SCJN resuelven las contradicciones entre Salas o Plenos Regionales; los Plenos Regionales resuelven las que se susciten entre Tribunales Colegiados de su región."),
        227 to ArticleMeta("Legitimación para Denunciar la Contradicción", "Jurisprudencia", "Podrán denunciar contradicción de criterios: los ministros de la SCJN, los magistrados de Plenos Regionales o Tribunales Colegiados, los Jueces de Distrito, el FGR y las partes procesales."),
        228 to ArticleMeta("Sustanciación Sumaria de la Contradicción de Criterios", "Jurisprudencia", "Radicada la denuncia, el órgano competente solicitará copias certificadas a los tribunales contendientes y turnará el expediente al ponente para resolver dentro del término de treinta días."),
        229 to ArticleMeta("Efectos Vinculantes de la Tesis Jurisprudencial Unificada", "Jurisprudencia", "La resolución que resuelva la contradicción de criterios fijará la jurisprudencia obligatoria sin afectar en ningún caso las situaciones jurídicas concretas de los juicios en que se dictaron los fallos."),
        230 to ArticleMeta("Interrupción y Modificación de Jurisprudencia", "Jurisprudencia", "La jurisprudencia obligatoria se interrumpe y pierde su fuerza cuando se pronuncie sentencia en contrario con las mismas mayorías exigidas para su creación."),
        231 to ArticleMeta("Declaratoria General de Inconstitucionalidad", "Inconstitucionalidad", "Cuando las Salas o el Pleno de la SCJN en juicios de amparo indirecto en revisión resuelvan por segunda ocasión consecutiva la inconstitucionalidad de una norma general, lo notificarán al órgano emisor."),
        232 to ArticleMeta("Plazo de 90 Días al Órgano Legislativo Emisor", "Inconstitucionalidad", "El órgano emisor de la norma general inconstitucional dispondrá de un plazo improrrogable de noventa días naturales para superar el problema de inconstitucionalidad mediante reforma legislativa."),
        233 to ArticleMeta("Aprobación de la Declaratoria General por 8 Votos", "Inconstitucionalidad", "Transcurrido el plazo de 90 días sin que se reforme la norma, el Pleno de la Suprema Corte emitirá la declaratoria general de inconstitucionalidad con mayoría calificada de al menos ocho votos."),
        234 to ArticleMeta("Efectos Abrogatorios y Publicación en el DOF", "Inconstitucionalidad", "La declaratoria general de inconstitucionalidad se publicará en el Diario Oficial de la Federación y producirá efectos generales expulsando definitivamente la norma del orden jurídico nacional."),
        235 to ArticleMeta("Excepción en Materia Tributaria y Fiscal", "Inconstitucionalidad", "La declaratoria general de inconstitucionalidad en ningún caso podrá aplicarse a normas generales expedidas en materia tributaria o hacendaria federal."),
        236 to ArticleMeta("Catálogo de Medidas de Apremio Judiciales", "Sanciones", "Para hacer cumplir sus determinaciones los juzgadores federales podrán hacer uso de: multa, auxilio de la fuerza pública federal o estatal, y denuncia penal ante el Ministerio Público."),
        237 to ArticleMeta("Régimen y Procedimiento de Sanciones Administrativas", "Sanciones", "Las multas procesales se impondrán previa vista a la persona infractora para que manifieste lo que a su derecho convenga en el plazo perentorio de tres días."),
        238 to ArticleMeta("Tasación de Sanciones Económicas en UMA", "Sanciones", "Las multas previstas en esta ley se tasarán en Unidades de Medida y Actualización (UMA) conforme a su valor oficial diario fijado por el INEGI al momento de cometerse la infracción."),
        239 to ArticleMeta("Cobro Coactivo de Multas a través del SAT", "Sanciones", "Las resoluciones que impongan sanciones económicas firmes se remitirán al Servicio de Administración Tributaria (SAT) para su cobro coactivo mediante el procedimiento administrativo de ejecución."),
        240 to ArticleMeta("Responsabilidad Administrativa Grave por Desacato", "Sanciones", "El desacato a un mandamiento judicial de amparo constituye falta administrativa grave y motivará la inmediata destitución e inhabilitación para el servicio público hasta por diez años."),
        241 to ArticleMeta("Denuncia Penal Inmediata ante la FGR", "Delitos en Amparo", "Cuando el juzgador federal advierta la comisión de conductas constitutivas de delito en el juicio de amparo, formulará de inmediato la denuncia correspondiente ante el Ministerio Público de la Federación."),
        242 to ArticleMeta("Consignación Penal Federal ante Juez de Distrito", "Delitos en Amparo", "El Ministerio Público consignará la carpeta de investigación penal iniciada contra servidores públicos contumaces directamente ante el Juez de Control Federal competente."),
        243 to ArticleMeta("Competencia Penal Federal para Juzgar Ilícitos", "Delitos en Amparo", "Los delitos cometidos en los procedimientos de amparo son del fuero federal estricto y se juzgarán conforme a las disposiciones penales de esta Ley y del Código Penal Federal."),
        244 to ArticleMeta("Prisión Preventiva Justificada en Delitos de Desacato", "Delitos en Amparo", "El juez penal podrá imponer la medida cautelar de prisión preventiva a los servidores públicos imputados por desacato doloso cuando exista riesgo comprobado de fuga o manipulación probatoria."),
        245 to ArticleMeta("Sanción Penal a Servidores por Resistencia Dolosa", "Delitos en Amparo", "Se impondrá pena de tres a nueve años de prisión a los funcionarios que con dolo se nieguen a cumplimentar un mandamiento de suspensión o sentencia protectora ejecutoria."),
        246 to ArticleMeta("Sanciones a Litigantes por Promociones Temerarias", "Delitos en Amparo", "Se sancionará a los abogados patronos que promuevan juicios de amparo basándose en hechos falsos u ocultando con dolo las resoluciones definitivas emitidas con anterioridad."),
        247 to ArticleMeta("Delito de Declaración Falsa ante Órgano de Amparo", "Delitos en Amparo", "Se impondrá prisión de dos a seis años y multa pecuniaria a la parte o testigo que declare con falsedad ante la autoridad de amparo bajo protesta de decir verdad."),
        248 to ArticleMeta("Responsabilidad de Peritos por Dictámenes Mendaces", "Delitos en Amparo", "Los peritos que emitan dictámenes manifiestamente falsos en la audiencia incidental o constitucional serán inhabilitados de cinco a diez años y acreedores a penas de prisión federal."),
        249 to ArticleMeta("Delito por Alteración de Sellos y Notificaciones", "Delitos en Amparo", "Quien destruya, altere o sustraiga listas de acuerdos o notificaciones oficiales de los estrados del tribunal de amparo incurrirá en sanciones privativas de la libertad de dos a cinco años."),
        250 to ArticleMeta("Agravantes por Reincidencia en Obstrucción Judicial", "Delitos en Amparo", "Las penas de prisión y multas pecuniarias se incrementarán hasta en una mitad cuando el servidor público infractor sea reincidente en conductas de desacato procesal."),
        251 to ArticleMeta("Sanción por Falsa Suposición de Actos de Autoridad", "Delitos en Amparo", "Se sancionará con prisión de tres a ocho años a quien simule la existencia de actos de autoridad inexistentes para obtener indebidamente la suspensión provisional de amparo."),
        252 to ArticleMeta("Responsabilidad Solidaria de Abogados y Apoderados", "Delitos en Amparo", "Los mandatarios judiciales y apoderados legales responderán solidariamente de los delitos y multas cometidos en nombre de sus representados cuando hayan actuado con dolo directo."),
        253 to ArticleMeta("Sanción a Actuarios por Falsedad en Notificaciones", "Delitos en Amparo", "El actuario judicial que asiente constancias falsas en cédulas o citatorios de notificación será inmediatamente destituido de su cargo y sancionado con pena de cuatro a ocho años de prisión."),
        254 to ArticleMeta("Delito por Cobro Indebido de Servicios Gratuitos", "Delitos en Amparo", "Los servidores públicos del PJF que exijan pagos o dádivas para tramitar promociones o practicar notificaciones incurrirán en el delito de concusión agravada."),
        255 to ArticleMeta("Medidas Disciplinarias ante el CJF", "Delitos en Amparo", "Sin perjuicio de la responsabilidad penal, los juzgadores federales remitirán copias de autos al Consejo de la Judicatura Federal para los procedimientos disciplinarios conducentes."),
        256 to ArticleMeta("Sanciones por Colusión Procesal Ilícita", "Delitos en Amparo", "Se impondrán de cuatro a diez años de prisión a las autoridades y litigantes que concierten actos simulados para inducir a error al juzgador de amparo en perjuicio de terceros."),
        257 to ArticleMeta("Delito por Sustracción de Expedientes y Evidencias", "Delitos en Amparo", "Quien sustraiga u oculte dolosamente autos, documentos originales o evidencias físicas incorporadas al expediente de amparo incurrirá en delito contra la administración de justicia."),
        258 to ArticleMeta("Delito de Resistencia a la Ejecución del Fallo", "Delitos en Amparo", "Los particulares que impidan por la fuerza material el cumplimiento de una sentencia de amparo protectora serán castigados con penas de dos a seis años de prisión y decomiso."),
        259 to ArticleMeta("Inhabilitación Definitiva para Ejercer la Abogacía", "Delitos en Amparo", "Los profesionales del derecho sentenciados por delitos cometidos en juicios de amparo sufrirán además la cancelación definitiva de su cédula profesional y prohibición de litigar."),
        260 to ArticleMeta("Sanción Penal a la Responsable por Falsedad en Informes", "Delitos en Amparo", "Se impondrá pena de tres a nueve años de prisión a la autoridad responsable que afirme una falsedad o niegue la verdad en su informe justificado o previo."),
        261 to ArticleMeta("Delito del Quejoso por Falso Testimonio u Ocultación", "Delitos en Amparo", "Se sancionará con pena de dos a seis años de prisión y multa al quejoso o tercero que al formular su demanda o comparecencia afirme hechos falsos u omita los que le consten con el ánimo de engañar."),
        262 to ArticleMeta("Delito de Desobediencia Flagrante a la Suspensión", "Delitos en Amparo", "Se impondrá pena de tres a nueve años de prisión, multa, destitución e inhabilitación de tres a nueve años al servidor público que no obedezca un auto de suspensión debidamente notificado."),
        263 to ArticleMeta("Agravación de Penas por Violación a la Suspensión de Plano", "Delitos en Amparo", "Si la desobediencia recae sobre una orden de suspensión concedida de oficio y de plano respecto a privación de la vida o libertad, las penas de prisión se aumentarán hasta en una mitad."),
        264 to ArticleMeta("Tipo Penal Especial de Repetición del Acto Reclamado", "Delitos en Amparo", "Comete delito federal la autoridad responsable que con conocimiento reitere el acto declarado inconstitucional, sancionándose con prisión de tres a nueve años y destitución definitiva."),
        265 to ArticleMeta("Normas de Vigencia y Disposiciones Transitorias", "Disposiciones Finales", "Esta Ley de Amparo rige en toda la República Mexicana y sus normas son de orden público y observancia irrenunciable para todos los tribunales y autoridades del país."),
        266 to ArticleMeta("Abrogación de la Ley de Amparo Anterior", "Disposiciones Finales", "Se abroga la Ley de Amparo, Reglamentaria de los Artículos 103 y 107 de la Constitución Política de los Estados Unidos Mexicanos publicada en el DOF el 10 de enero de 1936."),
        267 to ArticleMeta("Régimen de Transición para Juicios en Trámite", "Disposiciones Finales", "Los juicios de amparo iniciados con anterioridad a la entrada en vigor de la presente Ley continuarán tramitándose hasta su total resolución conforme a las disposiciones vigentes al momento de su inicio."),
        268 to ArticleMeta("Reglas de Transición para Recursos Pendientes", "Disposiciones Finales", "Los recursos interpuestos antes de las reformas se sustanciarán con arreglo a las disposiciones adjetivas aplicables en la fecha de su interposición formal."),
        269 to ArticleMeta("Vigencia de Tesis Jurisprudenciales Anteriores", "Disposiciones Finales", "La jurisprudencia integrada con anterioridad continuará en vigor en lo que no se oponga a la presente Ley y en tanto no sea expresamente interrumpida o sustituida."),
        270 to ArticleMeta("Plazos de Adecuación a Sistemas Digitales y PJF", "Disposiciones Finales", "El Consejo de la Judicatura Federal y la Suprema Corte emitirán los acuerdos generales para la interconexión informática y firma electrónica en los tribunales del país."),
        271 to ArticleMeta("Publicación y Entrada en Vigor del Ordenamiento", "Disposiciones Finales", "El presente ordenamiento entró en vigor al día siguiente de su publicación en el Diario Oficial de la Federación, vinculando obligatoriamente a todas las autoridades de los Estados Unidos Mexicanos.")
    )
}
